INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'contribution', 'n.', '/ˌkɒntrɪˈbjuːʃ(ə)n/', '贡献;捐款;捐助', 'Even a small contribution can help build a well in Africa.', '即使一点小小的贡献也能帮助在非洲打一口井。', 'Making a Difference', 1, 0, 'senior', 'wordlist', 'required3', 'U2', 'make a contribution', NULL, 'fltrp');
