INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'persuade', 'v.', '/pəˈsweɪd/', '说服;劝说', 'Ryan persuaded his classmates to donate money for a well.', '瑞安说服同学们捐钱打井。', 'Making a Difference', 45, 0, 'senior', 'wordlist', 'required3', 'U2', 'persuade others to', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'well', 'n.', '/wel/', '水井;井', 'A new well was built near the village school.', '村里的学校旁边打了一口新井。', 'Making a Difference', 46, 0, 'senior', 'wordlist', 'required3', 'U2', 'dig a well', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'pump', 'n.', '/pʌmp/', '泵;抽水机', 'Seventy dollars was only enough for a hand pump.', '七十美元只够买一个手动抽水机。', 'Making a Difference', 47, 0, 'senior', 'wordlist', 'required3', 'U2', 'a hand pump', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'purify', 'v.', '/ˈpjʊərɪfaɪ/', '净化;使纯净', 'Some villages collect and purify rainwater for drinking.', '一些村庄收集并净化雨水以供饮用。', 'Making a Difference', 48, 0, 'senior', 'wordlist', 'required3', 'U2', 'purify water', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'inspire', 'v.', '/ɪnˈspaɪə/', '激励;鼓舞;启发', 'Ryan''s story inspired many people to help children in Africa.', '瑞安的故事激励许多人去帮助非洲的孩子。', 'Making a Difference', 49, 0, 'senior', 'wordlist', 'required3', 'U2', 'inspire others', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'delighted', 'adj.', '/dɪˈlaɪtɪd/', '高兴的;快乐的', 'The delighted students sang and danced to welcome him.', '兴高采烈的学生们又唱又跳地欢迎他。', 'Making a Difference', 50, 0, 'senior', 'wordlist', 'required3', 'U2', 'be delighted to', NULL, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('f3u2.01', '①-ed 分词前置作定语(a broken cup / a finished well)', 'A2', 10, '外研社版必修第三册 U2 — 单个 -ed 分词放在名词前作定语,中心词是动作的承受者,含被动或已完成之意;主动的 -ing 不成立,因为名词不是动作的发出者。', 1, 'required3', 'U2', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('f3u2.02', '②-ed 分词短语后置作定语(= 被动定语从句:the well built in 1990)', 'A2', 10, '外研社版必修第三册 U2 — -ed 分词带短语放在名词后作定语,等于一个被动的定语从句(which/that + be done);中心词被动作用,故用过去分词,而非 -ing 或限定动词。', 2, 'required3', 'U2', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('f3u2.03', '③-ed 与 -ing 作定语的区分(被动 -ed vs 主动 -ing)', 'A2', 10, '外研社版必修第三册 U2 — 中心词是动作/情感的承受者用 -ed(被动/已完成);若发出动作或使人产生感受才用 -ing。本点中心词均为承受者,故 -ed 唯一成立。', 3, 'required3', 'U2', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U2' AND code='f3u2.01'), 'In Uganda, Ryan at last saw the ____ well with his own eyes.', 'finished', 'finishing', 'to finish', 'finish', 'A', '井是被完成的对象,用过去分词表已完成/被动 → finished;井不会主动完成,故 -ing 不成立。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U2' AND code='f3u2.01'), 'He gave the ____ money to a local charity that builds wells.', 'donating', 'donated', 'to donate', 'donate', 'B', '钱是被捐出的,过去分词表被动 → donated;钱不会主动捐,-ing 不成立。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U2' AND code='f3u2.01'), 'The villagers could no longer use the ____ pump after the storm.', 'breaking', 'to break', 'broken', 'break', 'C', '泵是被弄坏的,过去分词表被动/已完成 → broken。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U2' AND code='f3u2.01'), 'The children happily drank from a newly ____ well.', 'building', 'to build', 'build', 'built', 'D', '井是被建造的,过去分词表被动 → built。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U2' AND code='f3u2.01'), 'The ____ funds were used to dig more wells in the area.', 'raised', 'raising', 'to raise', 'raise', 'A', '资金是被筹集的,过去分词表被动 → raised。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U2' AND code='f3u2.01'), 'After it was cleaned, the ____ rainwater was safe to drink.', 'collecting', 'collected', 'to collect', 'collect', 'B', '雨水是被收集的,过去分词表被动/已完成 → collected。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U2' AND code='f3u2.01'), 'The village now uses ____ water to grow its vegetables.', 'recycling', 'to recycle', 'recycled', 'recycle', 'C', '水是被回收处理的,过去分词表被动 → recycled。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U2' AND code='f3u2.01'), 'Everyone celebrated the ____ project at the village school.', 'completing', 'to complete', 'complete', 'completed', 'D', '工程是被完成的,过去分词表已完成 → completed。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U2' AND code='f3u2.01'), 'Workers repaired the ____ road soon after the flood.', 'damaged', 'damaging', 'to damage', 'damage', 'A', '道路是被损坏的,过去分词表被动 → damaged。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U2' AND code='f3u2.01'), 'The clerk handed me a ____ form to fill in.', 'printing', 'printed', 'to print', 'print', 'B', '表格是被印好的,过去分词表已完成 → printed。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U2' AND code='f3u2.01'), 'In 1988, Grete found a ____ journal at the back of a drawer.', 'forgetting', 'to forget', 'forgotten', 'forget', 'C', '日记是被遗忘的,过去分词表被动/已完成 → forgotten。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U2' AND code='f3u2.01'), 'The ____ water was finally clean enough for the children.', 'purifying', 'to purify', 'purify', 'purified', 'D', '水是被净化的,过去分词表被动 → purified。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U2' AND code='f3u2.01'), 'The ____ school received new books from the foundation.', 'funded', 'funding', 'to fund', 'fund', 'A', '学校是被资助的对象,过去分词表被动 → funded。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U2' AND code='f3u2.01'), 'It was a well-____ event that raised a lot of money.', 'organising', 'organised', 'to organise', 'organise', 'B', '活动是被组织的,过去分词表被动 → organised。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U2' AND code='f3u2.01'), 'The ____ story soon reached people all over the country.', 'publishing', 'to publish', 'published', 'publish', 'C', '故事是被发表的,过去分词表被动/已完成 → published。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U2' AND code='f3u2.01'), 'He kept the ____ names of all the rescued children.', 'recording', 'to record', 'record', 'recorded', 'D', '名字是被记录下来的,过去分词表已完成 → recorded。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U2' AND code='f3u2.01'), 'The ____ supplies arrived at the village right on time.', 'delivered', 'delivering', 'to deliver', 'deliver', 'A', '物资是被送达的,过去分词表被动 → delivered。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U2' AND code='f3u2.01'), 'A ____ crowd waited at the station to welcome the visitor.', 'gathering', 'gathered', 'to gather', 'gather', 'B', '人群是被聚集起来的,过去分词表已完成 → gathered。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U2' AND code='f3u2.01'), 'They carefully followed the ____ schedule for the charity run.', 'planning', 'to plan', 'planned', 'plan', 'C', '日程是被计划好的,过去分词表已完成 → planned。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U2' AND code='f3u2.01'), 'Volunteers washed the windows, and the ____ glass shone again.', 'cleaning', 'to clean', 'clean', 'cleaned', 'D', '玻璃是被擦净的,过去分词表已完成/被动 → cleaned。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U2' AND code='f3u2.02'), 'Ryan could hardly believe the words ____ by his teacher.', 'spoken', 'speaking', 'to speak', 'spoke', 'A', 'words 被老师说出,后置过去分词短语 = 被动定语从句(which were spoken)→ spoken;无关系词时 spoke 这种限定动词不成立。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U2' AND code='f3u2.02'), 'The well ____ near the school changed the children''s lives.', 'building', 'built', 'to build', 'build', 'B', 'well 被建在学校旁,过去分词短语表被动 → built。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U2' AND code='f3u2.02'), 'The money ____ by his foundation supports many villages.', 'raising', 'to raise', 'raised', 'raise', 'C', 'money 被基金会筹集,过去分词短语表被动 → raised。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U2' AND code='f3u2.02'), 'The journal ____ at home contained the children''s names.', 'finding', 'to find', 'find', 'found', 'D', 'journal 被发现,过去分词短语表被动 → found。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U2' AND code='f3u2.02'), 'The children ____ by Winton grew up safely in Britain.', 'saved', 'saving', 'to save', 'save', 'A', 'children 被温顿拯救,过去分词短语表被动 → saved。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U2' AND code='f3u2.02'), 'The form ____ by Sarah was sent to the volunteer centre.', 'completing', 'completed', 'to complete', 'complete', 'B', 'form 被 Sarah 填好,过去分词短语表被动/已完成 → completed。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U2' AND code='f3u2.02'), 'The help ____ by the village included new water technology.', 'needing', 'to need', 'needed', 'need', 'C', 'help 是村庄所需要的,过去分词短语表被动 → needed。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U2' AND code='f3u2.02'), 'The homes ____ for the children were warm and safe.', 'preparing', 'to prepare', 'prepare', 'prepared', 'D', 'homes 被准备好,过去分词短语表被动/已完成 → prepared。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U2' AND code='f3u2.02'), 'The records ____ in his office later helped many families.', 'kept', 'keeping', 'to keep', 'keep', 'A', 'records 被保存在办公室,过去分词短语表被动 → kept。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U2' AND code='f3u2.02'), 'The honour ____ by the government made him very proud.', 'giving', 'given', 'to give', 'give', 'B', 'honour 被政府授予,过去分词短语表被动 → given。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U2' AND code='f3u2.02'), 'The photographs ____ years ago were still surprisingly clear.', 'taking', 'to take', 'taken', 'take', 'C', 'photographs 是多年前被拍下的,过去分词短语表被动 → taken。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U2' AND code='f3u2.02'), 'The gift ____ to the village brought everyone clean water.', 'sending', 'to send', 'send', 'sent', 'D', 'gift 被送往村庄,过去分词短语表被动 → sent。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U2' AND code='f3u2.02'), 'The clean water ____ to the village changed everything for them.', 'brought', 'bringing', 'to bring', 'bring', 'A', 'water 被带到村庄,过去分词短语表被动 → brought。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U2' AND code='f3u2.02'), 'The families ____ by the charity were deeply thankful.', 'helping', 'helped', 'to help', 'help', 'B', 'families 被慈善机构帮助,过去分词短语表被动 → helped。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U2' AND code='f3u2.02'), 'The wells ____ across Africa gave water to thousands of people.', 'digging', 'to dig', 'dug', 'dig', 'C', 'wells 被挖,过去分词短语表被动 → dug。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U2' AND code='f3u2.02'), 'The message ____ on the radio reached many kind listeners.', 'sharing', 'to share', 'share', 'shared', 'D', 'message 被在广播里分享,过去分词短语表被动 → shared。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U2' AND code='f3u2.02'), 'The clothes ____ by neighbours were given to poor families.', 'donated', 'donating', 'to donate', 'donate', 'A', 'clothes 被邻居捐出,过去分词短语表被动 → donated。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U2' AND code='f3u2.02'), 'The children ____ by volunteers slowly learned to read.', 'teaching', 'taught', 'to teach', 'teach', 'B', 'children 被志愿者教,过去分词短语表被动 → taught。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U2' AND code='f3u2.02'), 'The story ____ on television moved the whole audience.', 'telling', 'to tell', 'told', 'tell', 'C', 'story 被在电视上讲述,过去分词短语表被动 → told。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U2' AND code='f3u2.02'), 'The names ____ in the old journal belonged to rescued children.', 'writing', 'to write', 'wrote', 'written', 'D', 'names 被写在日记里,过去分词短语表被动 → written;无关系词时 wrote 不成立。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U2' AND code='f3u2.03'), 'The ____ children were too afraid to look at the soldiers.', 'frightened', 'frightening', 'to frighten', 'frighten', 'A', 'children 是受惊的一方(承受者),用 -ed → frightened;-ing 表''令人害怕的'',与孩子的感受不符。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U2' AND code='f3u2.03'), 'The ____ students sang and danced to welcome Ryan to the school.', 'delighting', 'delighted', 'to delight', 'delight', 'B', 'students 是感到高兴的一方,用 -ed → delighted。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U2' AND code='f3u2.03'), 'His ____ parents feared they might never see their son again.', 'worrying', 'to worry', 'worried', 'worry', 'C', 'parents 是担忧的一方,用 -ed → worried。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U2' AND code='f3u2.03'), 'Many ____ people decided to give money to the new foundation.', 'inspiring', 'to inspire', 'inspire', 'inspired', 'D', 'people 是被激励的一方,用 -ed → inspired。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U2' AND code='f3u2.03'), 'The ____ crowd cheered loudly as the well began to work.', 'excited', 'exciting', 'to excite', 'excite', 'A', 'crowd 是感到兴奋的一方,用 -ed → excited。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U2' AND code='f3u2.03'), 'The ____ audience could hardly believe what they had heard.', 'shocking', 'shocked', 'to shock', 'shock', 'B', 'audience 是受到震动的一方,用 -ed → shocked。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U2' AND code='f3u2.03'), 'She gave me a ____ look when she heard the wonderful news.', 'surprising', 'to surprise', 'surprised', 'surprise', 'C', 'look 体现她''感到惊讶'',承受者用 -ed → surprised。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U2' AND code='f3u2.03'), 'The ____ donors were happy to learn that their money had helped.', 'satisfying', 'to satisfy', 'satisfy', 'satisfied', 'D', 'donors 是感到满意的一方,用 -ed → satisfied。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U2' AND code='f3u2.03'), 'The ____ viewers cried as they watched his life story on TV.', 'moved', 'moving', 'to move', 'move', 'A', 'viewers 是被打动的一方,用 -ed → moved。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U2' AND code='f3u2.03'), 'The ____ boy worked hard for months until his dream came true.', 'determining', 'determined', 'to determine', 'determine', 'B', 'boy 是下定决心的承受者,用 -ed → determined。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U2' AND code='f3u2.03'), 'The charity sold the ____ bottles to raise money for schools.', 'recycling', 'to recycle', 'recycled', 'recycle', 'C', 'bottles 被回收,承受者用 -ed → recycled。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U2' AND code='f3u2.03'), 'He carefully read the ____ letter from the grateful family.', 'writing', 'to write', 'write', 'written', 'D', 'letter 被写,承受者用 -ed → written。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U2' AND code='f3u2.03'), 'Everyone still remembered the ____ words of the brave man.', 'spoken', 'speaking', 'to speak', 'speak', 'A', 'words 被说出,承受者用 -ed → spoken。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U2' AND code='f3u2.03'), 'She was upset about the ____ promise that nobody kept.', 'breaking', 'broken', 'to break', 'break', 'B', 'promise 被打破,承受者用 -ed → broken。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U2' AND code='f3u2.03'), 'Volunteers collected the ____ leaflets after the event ended.', 'printing', 'to print', 'printed', 'print', 'C', 'leaflets 被印制,承受者用 -ed → printed。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U2' AND code='f3u2.03'), 'The ____ clothes were washed and then given to poor families.', 'cleaning', 'to clean', 'clean', 'cleaned', 'D', 'clothes 被清洗,承受者用 -ed → cleaned。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U2' AND code='f3u2.03'), 'The ____ well gave the whole village fresh water at last.', 'dug', 'digging', 'to dig', 'dig', 'A', 'well 被挖,承受者用 -ed → dug。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U2' AND code='f3u2.03'), 'The ____ lives gave Winton great happiness in his later years.', 'saving', 'saved', 'to save', 'save', 'B', 'lives 被拯救,承受者用 -ed → saved。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U2' AND code='f3u2.03'), 'They reached the ____ goal and celebrated with a big party.', 'achieving', 'to achieve', 'achieved', 'achieve', 'C', 'goal 被实现,承受者用 -ed → achieved。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U2' AND code='f3u2.03'), 'The ____ children warmly thanked the kind volunteers.', 'helping', 'to help', 'help', 'helped', 'D', 'children 被帮助,承受者用 -ed → helped。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'The Boy Who Dug Wells', 'Ryan was a six-year-old boy in Canada when he first heard that many children in Africa could not get clean water. At his school a drinking fountain stood only ten steps away, so he could not understand why others had to walk for hours every single day. He decided to help. First he cleaned windows and did gardening to earn money, but he soon learned that a real well cost two thousand dollars, far more than his first seventy. Instead of giving up, Ryan asked his classmates and neighbours to donate, and a friend of his mother helped share his story with others. After several months he had raised enough, and a well was built near a school in Uganda. The grateful children no longer had to walk for hours, and they invited him to come and visit. Today his foundation has brought safe water to hundreds of thousands of people across Africa.', '记叙·瑞安的井', 153, '[{"q":"Why couldn''t Ryan understand the African children''s problem at first?","answer":"A","options":["Clean water was extremely easy for him to reach at home.","He had never drunk any water before.","He was living in Africa himself.","He disliked drinking water of any kind."],"explanation":"原文说他的饮水器只有十步远(''only ten steps away''),即取水极方便,故难以理解他人要走几小时;此为转述。"},{"q":"What did Ryan do when he found that a well cost far more than he had?","answer":"B","options":["He simply abandoned the whole plan.","He kept going and asked others to give money.","He built the well entirely on his own.","He decided to keep all the money for himself."],"explanation":"原文 ''Instead of giving up… asked his classmates and neighbours to donate'' 的转述。"},{"q":"What has Ryan''s foundation achieved according to the text?","answer":"A","options":["It has given safe water to very many people in Africa.","It has closed down all the wells it built.","It has stopped helping children in need.","It has moved all its work back to Canada."],"explanation":"末句 ''brought safe water to hundreds of thousands of people across Africa'' 的转述。"}]'::jsonb, '[{"word":"fountain","cn":"饮水器;喷泉"},{"word":"donate","cn":"捐赠"},{"word":"grateful","cn":"感激的"}]'::jsonb, 2, 'required3', 'U2', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'The Quiet Hero of Prague', 'Nicholas Winton was a young British man who worked in business. In December 1938, a friend asked him to come to Prague, where many families were in great danger. Moved by what he saw there, Winton decided to bring children to safety in Britain. He set up an office, kept careful records, and found temporary homes for the children. He even used his own money to pay the fee that the government required for each child. By the summer of 1939, he had helped 669 children escape. After the war, Winton said little about what he had done, and his actions were almost forgotten. Then, in 1988, his wife found an old journal full of names and photographs. When his story finally appeared on a television programme, hundreds of the people he had saved stood up to thank him. Winton received many honours and lived to the age of 106.', '记叙·温顿救童', 150, '[{"q":"Why did Winton travel to Prague in 1938?","answer":"B","options":["He simply wanted to take a long holiday.","A friend invited him to rescue families facing danger.","He was looking for a better-paid job there.","He had been born and raised in the city."],"explanation":"原文 ''a friend asked him to come to Prague, where many families were in great danger'' 的转述。"},{"q":"How did people finally learn about Winton''s actions in 1988?","answer":"C","options":["He wrote and published a long book himself.","The government announced it to everyone.","His wife discovered the journal and a TV show revealed his story.","He told the whole story on the radio."],"explanation":"原文 ''his wife found an old journal… his story finally appeared on a television programme'' 的转述。"},{"q":"What happened when Winton''s story appeared on television?","answer":"D","options":["No one in the room seemed to remember him.","He refused to say a single word.","He immediately left Britain for good.","Many of those he had saved came forward to thank him."],"explanation":"原文 ''hundreds of the people he had saved stood up to thank him'' 的转述。"}]'::jsonb, '[{"word":"temporary","cn":"临时的"},{"word":"aid","cn":"援助"},{"word":"achievement","cn":"成就"}]'::jsonb, 2, 'required3', 'U2', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'A Gift to the World', 'Tu Youyou is a Chinese scientist who has made a great contribution to medicine. She was born in Ningbo in 1930 and later studied at a medical college in Beijing. In 1969, she became the leader of a research team that was looking for a treatment for malaria, a disease that had killed millions of people. After years of patient, careful work, her team managed to take a useful substance from a Chinese herb in 1972. This substance turned out to be very effective in fighting the illness. In 1986, she obtained an official certificate for the new drug. Her perseverance was finally recognised by the whole world in 2015, when she won the Nobel Prize in Medicine. Even after this great honour, she chose to do further research. Her story shows that patience and hard work can help one single person save countless lives.', '记叙·屠呦呦', 145, '[{"q":"What was the goal of the team that Tu Youyou led in 1969?","answer":"A","options":["To find a way of treating malaria.","To build a brand-new medical college.","To win an international science prize.","To move her family out of Beijing."],"explanation":"原文 ''a research team that was looking for a treatment for malaria'' 的转述。"},{"q":"Where did the useful substance against the disease come from?","answer":"B","options":["From a foreign-made medicine.","From a traditional Chinese herb.","From a large modern factory.","From a kind of wild animal."],"explanation":"原文 ''take a useful substance from a Chinese herb'' 的转述。"},{"q":"What does Tu Youyou''s story show, according to the text?","answer":"C","options":["Only good luck can bring real success.","Scientific work is mostly useless.","Patience and effort can help one save many lives.","Big prizes are usually easy to win."],"explanation":"末句 ''patience and hard work can help one single person save countless lives'' 的转述。"}]'::jsonb, '[{"word":"treatment","cn":"疗法"},{"word":"effective","cn":"有效的"},{"word":"perseverance","cn":"坚持不懈"}]'::jsonb, 2, 'required3', 'U2', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'Helping Children Everywhere', 'UNICEF is a famous organisation of the United Nations. The name is short for the United Nations Children''s Fund, and its main office is based in New York. UNICEF was founded in December 1946 to bring food and healthcare to children in countries that had been damaged in the Second World War. Over the years, its mission has been extended far beyond Europe. Today it helps children in the developing world, including those who live with diseases or a disability, and those whose lives are affected by fast change and environmental problems. The organisation now works in around 190 countries and territories. Wherever there is a child in need, UNICEF tries to offer assistance, from clean water and medicine to safe schools. Its long history shows how people around the world can work together to give every child a fairer start in life.', '说明·联合国儿童基金会', 143, '[{"q":"What was UNICEF first created to do in 1946?","answer":"D","options":["To build several offices in New York.","To sell medicine to rich countries.","To start a new world war.","To give food and medical help to children harmed by war."],"explanation":"原文 ''to bring food and healthcare to children in countries that had been damaged in the Second World War'' 的转述。"},{"q":"Who does UNICEF try to help today?","answer":"A","options":["Children in need, including those who are ill or disabled.","Only wealthy families in big cities.","Only adults living in Europe.","Only the people who work for it."],"explanation":"原文 ''helps children in the developing world, including those who live with diseases or a disability'' 的转述。"},{"q":"What does UNICEF''s work show, according to the writer?","answer":"B","options":["That charity work almost never succeeds.","That people worldwide can work together to help every child.","That children should only help themselves.","That war is the best way to solve problems."],"explanation":"末句 ''people around the world can work together to give every child a fairer start'' 的转述。"}]'::jsonb, '[{"word":"mission","cn":"使命"},{"word":"territory","cn":"地区"},{"word":"assistance","cn":"援助"}]'::jsonb, 2, 'required3', 'U2', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'Charity on the High Street', 'In Britain, helping others through charity is part of everyday life. Walk along almost any high street, and you will come across people raising money for good causes. Some are collecting for Cancer Research UK, while others stand for the British Heart Foundation or the Royal National Lifeboat Institution, which saves lives at sea. Many of these groups depend on volunteers, ordinary people who give their free time without any pay. Some sort clothes in charity shops, while others answer phones or organise events. Becoming a volunteer is usually simple: you fill in a registration form, and the centre sends a confirmation before you start. The work is not always easy, but most volunteers say it gives them a strong sense of purpose. They feel grateful for the chance to make a difference, however small, to people they may never even meet.', '说明·英国街头慈善', 142, '[{"q":"What will you often see on a British high street?","answer":"C","options":["Empty streets with no shops at all.","Doctors treating patients outdoors.","People collecting money for good causes.","Children walking to school together."],"explanation":"原文 ''you will come across people raising money for good causes'' 的转述。"},{"q":"What do the volunteers in the text usually do?","answer":"D","options":["Work only when the pay is very high.","Run the country''s government.","Stay at home and do nothing all day.","Give their free time to help without being paid."],"explanation":"原文 ''ordinary people who give their free time without any pay'' 的转述。"},{"q":"How do most volunteers feel about their work?","answer":"A","options":["It fills their lives with real meaning.","It is a complete waste of their time.","It quickly makes them very rich.","It is always dull and boring."],"explanation":"原文 ''it gives them a strong sense of purpose'' 的转述。"}]'::jsonb, '[{"word":"charity","cn":"慈善;慈善机构"},{"word":"registration","cn":"登记"},{"word":"confirmation","cn":"确认"}]'::jsonb, 2, 'required3', 'U2', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'Anna''s Saturdays', 'Anna is a senior high school student who spends her weekends as a volunteer. Every Saturday she goes to a centre that teaches young children with a disability. She is usually quite shy, yet she is also generous and never hesitates to help. At first some of the children were sensitive and did not want to join in, but Anna was patient and gentle, and slowly they began to trust her. She helps them paint, sing and play simple games, and she always cheers them up when they feel sad. Anna says that volunteering has taught her far more than any lesson at school. She has learned how to listen, how to be kind, and how a few warm words can change someone''s whole day. For her, making a difference does not need money or fame; it only needs a caring heart and a little free time.', '记叙·学生志愿者', 147, '[{"q":"What does Anna do on Saturdays?","answer":"B","options":["She earns money working in a shop.","She helps teach young children who have a disability.","She studies hard for her exams.","She travels to other countries."],"explanation":"原文 ''a centre that teaches young children with a disability'' 的转述。"},{"q":"How did Anna slowly win the children''s trust?","answer":"C","options":["By giving each of them money.","By being strict and very loud.","By being patient and gentle with them.","By ignoring them completely."],"explanation":"原文 ''Anna was patient and gentle… they began to trust her'' 的转述。"},{"q":"What does Anna believe making a difference really needs?","answer":"D","options":["A great deal of money and fame.","Many years of special study.","Expensive professional training only.","A kind heart and a little spare time."],"explanation":"末句 ''it only needs a caring heart and a little free time'' 的转述。"}]'::jsonb, '[{"word":"generous","cn":"慷慨的"},{"word":"sensitive","cn":"敏感的"},{"word":"hesitate","cn":"犹豫"}]'::jsonb, 2, 'required3', 'U2', 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required3', 'U2', 'Water for a Village', 'In many parts of the world, getting clean water is still a daily (1)____. In one small village, the children once had to walk for hours to (2)____ water from a dirty river. The water often made them (3)____, and many of them missed school. Then a charity decided to (4)____ a project to help. Workers came to (5)____ a deep well right in the centre of the village. They also taught the families how to (6)____ rainwater so that nothing was wasted. Slowly, life began to (7)____. The children grew healthy enough to study, and their parents could grow more food. The whole village felt deeply (8)____ to everyone who had helped. Their story is a clear (9)____ that even a little clean water can completely (10)____ people''s lives.', 130, 2, '[{"q":"1","answer":"A","options":["struggle","holiday","game","prize"],"explanation":"a daily struggle 每天的艰难;其余名词不合语境。"},{"q":"2","answer":"B","options":["sell","collect","throw","hide"],"explanation":"collect water 取/打水;sell/throw/hide 不合理。"},{"q":"3","answer":"C","options":["rich","tall","sick","late"],"explanation":"made them sick 使他们生病。"},{"q":"4","answer":"D","options":["stop","leave","lose","start"],"explanation":"start a project 启动项目。"},{"q":"5","answer":"A","options":["dig","eat","read","sing"],"explanation":"dig a well 挖井。"},{"q":"6","answer":"B","options":["waste","store","drop","sell"],"explanation":"store rainwater 储存雨水;与''nothing was wasted''呼应。"},{"q":"7","answer":"C","options":["fail","end","improve","fall"],"explanation":"life began to improve 生活开始好转。"},{"q":"8","answer":"D","options":["angry","afraid","bored","grateful"],"explanation":"grateful to 感激;后接帮助者。"},{"q":"9","answer":"A","options":["example","price","noise","secret"],"explanation":"a clear example 一个清楚的例子。"},{"q":"10","answer":"B","options":["break","change","sell","forget"],"explanation":"change people''s lives 改变生活。"}]'::jsonb, 1, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required3', 'U2', 'A Charity Sale at School', 'Last month, our class organised a charity (1)____ to raise money for children in need. Everyone was asked to bring something they no longer (2)____, such as old books, toys or clothes. We set up several (3)____ in the playground and put a fair price on each item. Many parents came to (4)____ our things, and some even gave extra money. My job was to (5)____ the money carefully and write down every sale. By the end of the day, we were all tired but very (6)____. Together we had raised over two thousand yuan. Our teacher said the money would be (7)____ to a local charity that helps poor families. She reminded us that even a small (8)____ can make a real difference. I felt proud that our simple idea had (9)____ so many people. Now we plan to hold a similar (10)____ every year.', 146, 2, '[{"q":"1","answer":"C","options":["sleep","fight","sale","rain"],"explanation":"a charity sale 慈善义卖。"},{"q":"2","answer":"D","options":["sold","broke","lost","wanted"],"explanation":"no longer wanted 不再想要的(东西)。"},{"q":"3","answer":"A","options":["tables","rivers","clouds","songs"],"explanation":"set up tables 摆好桌子;后文''put a price on each item''。"},{"q":"4","answer":"B","options":["throw","buy","hide","lose"],"explanation":"came to buy 来买东西。"},{"q":"5","answer":"C","options":["eat","draw","count","sing"],"explanation":"count the money 数钱。"},{"q":"6","answer":"D","options":["angry","afraid","bored","happy"],"explanation":"tired but happy 累但开心。"},{"q":"7","answer":"A","options":["given","sold","thrown","hidden"],"explanation":"money would be given to a charity 捐给慈善机构。"},{"q":"8","answer":"B","options":["mistake","contribution","noise","price"],"explanation":"a small contribution 小小的贡献。"},{"q":"9","answer":"C","options":["hurt","ignored","helped","blamed"],"explanation":"had helped so many people 帮助了那么多人。"},{"q":"10","answer":"D","options":["error","prize","storm","event"],"explanation":"a similar event 类似的活动。"}]'::jsonb, 2, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required3', 'U2', 'Becoming a Volunteer', 'My sister always wanted to (1)____ others, so last summer she decided to become a (2)____. First, she searched online for a centre that (3)____ help with old people. Then she made a phone (4)____ to ask about the work. The lady who answered was very kind and explained everything (5)____. My sister had to fill in a (6)____ form and then wait for a (7)____ before she could start. On her first day she felt a little (8)____, but everyone made her feel welcome. Now she visits the centre three times a week. She reads to the old people, listens to their stories and helps them with small (9)____. She says that volunteering has made her more patient and (10)____. It is hard work, but she has never once thought about giving up.', 134, 2, '[{"q":"1","answer":"A","options":["help","hurt","leave","ignore"],"explanation":"wanted to help others 想帮助别人。"},{"q":"2","answer":"B","options":["customer","volunteer","stranger","winner"],"explanation":"become a volunteer 成为志愿者。"},{"q":"3","answer":"C","options":["sold","broke","offered","lost"],"explanation":"a centre that offered help 提供帮助的中心。"},{"q":"4","answer":"D","options":["song","game","meal","call"],"explanation":"made a phone call 打了个电话。"},{"q":"5","answer":"A","options":["clearly","hardly","rudely","never"],"explanation":"explained everything clearly 解释得很清楚。"},{"q":"6","answer":"B","options":["weather","registration","price","noise"],"explanation":"a registration form 登记表。"},{"q":"7","answer":"C","options":["holiday","mistake","confirmation","storm"],"explanation":"wait for a confirmation 等确认。"},{"q":"8","answer":"D","options":["rich","tall","late","nervous"],"explanation":"felt a little nervous 有点紧张。"},{"q":"9","answer":"A","options":["tasks","prices","songs","storms"],"explanation":"small tasks 小事/小活儿。"},{"q":"10","answer":"B","options":["lazy","kind","rude","selfish"],"explanation":"more patient and kind 更有耐心、更善良。"}]'::jsonb, 3, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required3', 'U2', 'Old Clothes, New Hope', 'Every winter, our neighbourhood holds a drive to collect warm (1)____ for families who cannot afford them. People bring coats, gloves and blankets that they no longer (2)____. Volunteers then (3)____ everything into boxes by size and colour. Clothes that are dirty are washed, and those that are torn are (4)____ by kind grandmothers. The clean, tidy clothes are then (5)____ to shelters around the city. Last year I joined the drive for the first time. At first I thought my small (6)____ would not matter much. But when I saw how (7)____ the families were, I understood that even one coat could keep a child warm. One little girl gave me a huge (8)____ when she put on her new gloves. That moment (9)____ me to keep helping. Now I look (10)____ to the clothes drive every single winter.', 140, 2, '[{"q":"1","answer":"C","options":["prices","songs","clothes","storms"],"explanation":"warm clothes 暖和的衣物。"},{"q":"2","answer":"D","options":["sell","drive","cook","need"],"explanation":"no longer need 不再需要的;sell/drive/cook 不合理。"},{"q":"3","answer":"A","options":["sort","eat","sing","drive"],"explanation":"sort everything into boxes 把东西分类装箱。"},{"q":"4","answer":"B","options":["sold","mended","lost","eaten"],"explanation":"torn clothes are mended 破的被缝补。"},{"q":"5","answer":"C","options":["asked","called","sent","named"],"explanation":"sent to shelters 送往收容所。"},{"q":"6","answer":"D","options":["noise","price","storm","effort"],"explanation":"my small effort 我小小的付出。"},{"q":"7","answer":"A","options":["grateful","angry","bored","afraid"],"explanation":"how grateful the families were 家庭们多么感激。"},{"q":"8","answer":"B","options":["shout","smile","price","storm"],"explanation":"gave me a huge smile 给我一个大大的微笑。"},{"q":"9","answer":"C","options":["stopped","refused","inspired","forced"],"explanation":"inspired me to keep helping 激励我继续帮忙。"},{"q":"10","answer":"D","options":["back","away","down","forward"],"explanation":"look forward to 期待。"}]'::jsonb, 4, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required3', 'U2', 'Reading to Children', 'Once a week, a group of students from our school (1)____ a nearby hospital to read to sick children. Many of these children must stay in bed for a long (2)____ and often feel lonely. A good story can help them (3)____ their pain for a while and smile again. Before we go, we carefully (4)____ books that are funny and full of hope. When we read, we use different voices to make each character come (5)____. The children listen with wide eyes and often ask us to read the same story (6)____. Their happiness is the best (7)____ we could ask for. One boy told me that our visits were the part of the week he (8)____ most. Hearing that, I felt that our time was truly well (9)____. Reading to others costs nothing, yet it can bring great (10)____ to a child in need.', 146, 2, '[{"q":"1","answer":"A","options":["visit","build","sell","drive"],"explanation":"students visit a hospital 学生探访医院。"},{"q":"2","answer":"B","options":["price","time","song","storm"],"explanation":"for a long time 很长时间。"},{"q":"3","answer":"C","options":["sell","count","forget","drive"],"explanation":"forget their pain 暂时忘记疼痛。"},{"q":"4","answer":"D","options":["throw","break","lose","choose"],"explanation":"choose books 挑选书。"},{"q":"5","answer":"A","options":["alive","asleep","angry","late"],"explanation":"come alive 变得活灵活现。"},{"q":"6","answer":"B","options":["never","again","hardly","nowhere"],"explanation":"read the same story again 再读一遍。"},{"q":"7","answer":"C","options":["mistake","noise","reward","price"],"explanation":"the best reward 最好的回报。"},{"q":"8","answer":"D","options":["hated","feared","broke","enjoyed"],"explanation":"the part he enjoyed most 他最喜欢的部分。"},{"q":"9","answer":"A","options":["spent","sold","lost","broken"],"explanation":"time well spent 时间花得值。"},{"q":"10","answer":"B","options":["noise","joy","price","storm"],"explanation":"bring great joy 带来巨大的快乐。"}]'::jsonb, 5, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required3', 'U2', 'A Green Way to Help', 'Our town has found a clever way to (1)____ money for charity while also caring for the (2)____. People are asked to bring empty bottles and cans to a special (3)____ at the supermarket. Instead of throwing this rubbish away, workers (4)____ it so that the materials can be used again. For every bag of bottles, the shop gives a small (5)____ of money to a children''s charity. In this way, families can help others without spending anything (6)____. The idea has been so (7)____ that several other towns have started to copy it. Last month alone, the scheme (8)____ enough money to buy books for a whole village school. It also keeps the streets (9)____ and teaches children to care for nature. Helping people and protecting the planet, it turns out, can easily go (10)____.', 136, 2, '[{"q":"1","answer":"C","options":["waste","lose","raise","hide"],"explanation":"raise money 筹钱。"},{"q":"2","answer":"D","options":["holiday","price","song","environment"],"explanation":"caring for the environment 关爱环境。"},{"q":"3","answer":"A","options":["point","river","cloud","storm"],"explanation":"a special point 一个专门的(回收)点。"},{"q":"4","answer":"B","options":["sell","recycle","eat","drive"],"explanation":"workers recycle it 工人回收它。"},{"q":"5","answer":"C","options":["noise","mistake","amount","storm"],"explanation":"a small amount of money 一小笔钱。"},{"q":"6","answer":"D","options":["never","hardly","nowhere","extra"],"explanation":"without spending anything extra 不必额外花钱。"},{"q":"7","answer":"A","options":["effective","boring","useless","ugly"],"explanation":"so effective that 如此有效以至于。"},{"q":"8","answer":"B","options":["lost","raised","wasted","broke"],"explanation":"the scheme raised enough money 计划筹到足够的钱。"},{"q":"9","answer":"C","options":["dirty","dark","clean","empty"],"explanation":"keeps the streets clean 让街道整洁。"},{"q":"10","answer":"D","options":["apart","away","back","together"],"explanation":"go together 并行不悖。"}]'::jsonb, 6, 'fltrp');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U2 听力·对话 Joining a Charity Run', '外研社版必修第三册 U2 · dialogue', 3, 'Mia: Hi Tom, are you free next Sunday? I''m joining a charity run for the children''s hospital.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U2 听力·短文 Charity Shops', '外研社版必修第三册 U2 · passage', 2, 'On many British high streets, you will find charity shops.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U2 听力·对话 A Phone Enquiry', '外研社版必修第三册 U2 · dialogue', 3, 'Clerk: Good morning, Greenfield Volunteer Centre. How can I help you?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U2 听力·短文 Everyone Can Make a Difference', '外研社版必修第三册 U2 · passage', 2, 'You might think that only rich or famous people can help the world, but that is not true.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U2 听力·对话 A Book Donation', '外研社版必修第三册 U2 · dialogue', 3, 'Leo: Anna, our class is collecting books for a village school. Would you like to help?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U2 听力·短文 Why People Volunteer', '外研社版必修第三册 U2 · passage', 2, 'Have you ever wondered why so many people give their free time to help others for no pay?
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit, publisher) VALUES (10, 'Write a Short Biography of Someone Who Made a Difference(写一篇人物小传)', 'A Person Who Made a Difference', '请用英语写一篇约 80 词的人物小传,介绍一位''有所作为''的人(可以是屠呦呦、瑞安、温顿,也可以是你身边的人)。内容包括:① 他/她是谁、最大的成就是什么;② 按时间顺序写 2-3 件关键事迹;③ 他/她的个人品质,以及为什么激励你。注意:可用 -ed 分词作定语(如 the well built by him / the words spoken by her)。', 'Write a short biography (about 80 words) of a person who has made a difference, such as Tu Youyou, Ryan or someone you admire. Include: 1) who the person is and his/her greatest achievement; 2) two or three key actions in time order; 3) the person''s personal qualities and why he/she inspires you. Try to use the -ed participle as an attributive (e.g. the well built by him).', '["介绍人物与最大成就(… is a … who is best known for …)","按时间顺序写关键事迹(In 1969, … / Later, … / Finally, …)","总结个人品质并说明激励(His/Her perseverance inspires me to …)","尝试用 -ed 分词作定语(the money raised by …, the children saved by …)"]'::jsonb, 70, 100, 'Tu Youyou is a Chinese scientist best known for her work against malaria. Born in 1930, she studied medicine and later led a research team determined to find a cure. After years of patient work, the substance taken from a Chinese herb proved very effective, and millions of lives were saved. In 2015 she won the Nobel Prize. Her perseverance and quiet courage inspire me to keep trying, however hard the task. She shows that one determined person can truly make a difference.', '【15 分制】A 档(13-15):五要素齐全、组织有条理、语言准确多样;B 档(10-12):要点较全、少量错误;C 档(7-9):要点偏少、句型简单;D 档(0-6):内容不完整、错误多。', '["Tu Youyou is a Chinese scientist best known for her work against malaria.","She led a research team determined to find a cure.","The substance taken from a Chinese herb proved very effective, and millions of lives were saved.","She shows that one determined person can truly make a difference."]'::jsonb, '[{"wrong":"the words speaking by her teacher","correct":"the words spoken by her teacher","note":"words 是被说出的,被动含义用过去分词 spoken,不用 -ing。"},{"wrong":"the well builded near the school","correct":"the well built near the school","note":"build 的过去分词是 built,不是 builded。"},{"wrong":"Born in 1930, she study medicine.","correct":"Born in 1930, she studied medicine.","note":"记叙过去的事用一般过去时 studied。"}]'::jsonb, '【人物小传结构】
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content, publisher) VALUES (10, 'required3', 'U2', '{"title":"-ed 分词作定语(被动/完成含义)速查","intro":"-ed 分词作定语,核心是「中心词是动作的承受者」,表被动或已完成。判断口诀:东西被做 → 用 -ed;东西在做/使人怎样 → 用 -ing。短的放名词前(a broken cup),带短语的放名词后(the cup broken by him = which was broken by him)。","table":{"headers":["位置 / 形式","用法 · 例句 · 等价"],"rows":[["前置单个 -ed","a finished well / a broken pump:中心词被动作 → 用 -ed"],["后置 -ed 短语","the well built in 1990 = the well which was built in 1990(被动定语从句)"],["-ed vs -ing","the frightened children(孩子受惊)vs a frightening film(电影令人害怕)"],["承受者判断","看名词是''被做''还是''在做'':被做用 -ed,在做用 -ing"]]},"specialRules":[{"rule":"中心词是动作的承受者(被动/已完成)→ 用 -ed","mark":"the words spoken by his teacher(话被说出)"},{"rule":"后置 -ed 短语 = 被动定语从句,可还原成 which/that + be + done","mark":"the well built near the school = which was built near the school"},{"rule":"情感类:人''感到''用 -ed,事物''令人''用 -ing","mark":"the delighted students(学生很高兴)/ a delightful day"},{"rule":"不及物动词的 -ed 多表''已完成''而非被动","mark":"fallen leaves 落叶 / a retired teacher 退休教师"}],"why":["及物动词的 -ed 分词天然带被动含义(被…),所以当名词是动作的承受者时,用 -ed 最简洁,等于省去了 which/that is(are/was/were) 的被动定语从句。"],"gaokaoPoints":["语法填空/短文改错高频:给动词原形,判断该填 -ed(被动)还是 -ing(主动)。看名词是承受者还是发出者。","-ed 短语后置 = 被动定语从句的缩写,常与 -ing 短语(主动)对比考查。","情感动词(interest/excite/frighten/satisfy 等):修饰人多用 -ed,修饰物多用 -ing。"],"examVsReal":[{"exam":"the money raised by his foundation(考试/书面常用后置 -ed 短语)","real":"the money his foundation raised","note":"口语里常直接用定语从句、省略关系词,书面更爱用 -ed 短语显得简洁。"},{"exam":"the children saved by Winton(考试爱考被动 -ed)","real":"the kids Winton saved","note":"意思一样;考试看你会不会用过去分词的被动形式。"}]}'::jsonb, 'fltrp');
